import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:percent_indicator/linear_percent_indicator.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'dart:convert'; // Import do kodowania/dekodowania JSON

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await initializeDateFormatting(); // Inicjalizacja dla języka polskiego
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Timelapse App',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xFF6200EE),
          brightness: Brightness.dark,
          primary: const Color(0xFFBB86FC),
          secondary: const Color(0xFF03DAC6),
          tertiary: const Color(0xFF3700B3),
          surface: const Color(0xFF121212),
          background: const Color(0xFF121212),
        ),
        useMaterial3: true,
        fontFamily: 'Montserrat',
        scaffoldBackgroundColor: const Color(0xFF121212),
        cardTheme: CardTheme(
          elevation: 0,
          color: const Color(0xFF1E1E1E),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          margin: const EdgeInsets.symmetric(vertical: 8),
        ),
        appBarTheme: const AppBarTheme(
          centerTitle: true,
          elevation: 0,
          backgroundColor: Color(0xFF1E1E1E),
          foregroundColor: Colors.white,
        ),
        tabBarTheme: const TabBarTheme(
          labelColor: Colors.white,
          unselectedLabelColor: Colors.grey,
          indicatorColor: Color(0xFFBB86FC),
        ),
        dialogTheme: const DialogTheme(
          backgroundColor: Color(0xFF1E1E1E),
          titleTextStyle: TextStyle(color: Colors.white),
          contentTextStyle: TextStyle(color: Colors.white),
        ),
        textTheme: const TextTheme(
          displayLarge: TextStyle(fontSize: 32, fontWeight: FontWeight.bold, color: Colors.white),
          titleLarge: TextStyle(fontSize: 22, fontWeight: FontWeight.w600, color: Colors.white),
          bodyLarge: TextStyle(fontSize: 16, color: Colors.white),
        ),
      ),
      home: const Timelaps(),
    );
  }
}

// =========================================================================
// KLASY MODELU DANYCH
// =========================================================================

// Klasa Goal - teraz z możliwością mutacji progress i maxProgress oraz serializacją
class Goal {
  String id; // Unikalny ID celu, np. "silownia", "praca"
  String title;
  String description;
  double progress;
  double maxProgress;
  IconData icon; // Dodajemy ikonę dla lepszej wizualizacji

  Goal({
    required this.id,
    required this.title,
    required this.description,
    this.progress = 0,
    required this.maxProgress,
    this.icon = Icons.star, // Domyślna ikona
  });

  // Metoda do serializacji Goal do JSON
  Map<String, dynamic> toJson() => {
        'id': id,
        'title': title,
        'description': description,
        'progress': progress,
        'maxProgress': maxProgress,
        // Ikona nie jest serializowana, bo jest statyczna i odtworzymy ją po ID
      };

  // Konstruktor do deserializacji Goal z JSON
  factory Goal.fromJson(Map<String, dynamic> json) {
    // Tutaj musimy odtworzyć ikonę na podstawie ID,
    // albo przekazać ją jako argument z mapy definicji celów.
    // Dla prostoty, w tym przykładzie, odtworzymy ją na podstawie zmapowanych ID.
    IconData defaultIcon = Icons.star;
    switch (json['id']) {
      case 'pracady':
        defaultIcon = Icons.work;
        break;
      case 'silownia':
        defaultIcon = Icons.fitness_center;
        break;
      case 'boks':
        defaultIcon = Icons.sports_mma;
        break;
      case 'zarobek':
        defaultIcon = Icons.attach_money;
        break;
      case 'inf04':
        defaultIcon = Icons.computer;
        break;
      case 'matematyka':
        defaultIcon = Icons.calculate;
        break;
      case 'wyjazdy':
        defaultIcon = Icons.card_travel;
        break;
      // Dodaj więcej przypadków dla innych celów
    }

    return Goal(
      id: json['id'],
      title: json['title'],
      description: json['description'],
      progress: json['progress'] as double,
      maxProgress: json['maxProgress'] as double,
      icon: defaultIcon,
    );
  }
}

// Klasa Phase - teraz z możliwością mutacji goals oraz serializacją
class Phase {
  String title;
  DateTime startDate;
  DateTime endDate;
  String description;
  List<Goal> goals; // Lista celów dla tej fazy

  Phase({
    required this.title,
    required this.startDate,
    required this.endDate,
    required this.description,
    required this.goals,
  });

  // Metoda do serializacji Phase do JSON
  Map<String, dynamic> toJson() => {
        'title': title,
        'startDate': startDate.toIso8601String(),
        'endDate': endDate.toIso8601String(),
        'description': description,
        'goals': goals.map((g) => g.toJson()).toList(),
      };

  // Konstruktor do deserializacji Phase z JSON
  factory Phase.fromJson(Map<String, dynamic> json) {
    return Phase(
      title: json['title'],
      startDate: DateTime.parse(json['startDate']),
      endDate: DateTime.parse(json['endDate']),
      description: json['description'],
      goals: (json['goals'] as List<dynamic>)
          .map((g) => Goal.fromJson(g as Map<String, dynamic>))
          .toList(),
    );
  }
}

// =========================================================================
// GŁÓWNY WIDGET APLIKACJI
// =========================================================================

class Timelaps extends StatefulWidget {
  const Timelaps({Key? key}) : super(key: key);

  @override
  _HomePageState createState() => _HomePageState();
}

class _HomePageState extends State<Timelaps>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;

  // Daty projektu (całościowego) - ZMIENIONE NA 23.06.2025
  final DateTime projectStartDate = DateTime(2025, 6, 23);
  final DateTime projectEndDate = DateTime(2027, 6, 30); // Do końca Szkoły 2026/2027

  late DateTime currentDate;
  late Duration daysPassed;
  late Duration daysToGo;
  double totalProjectProgress = 0.0;
  int currentPhaseIndex = 0;

  List<Phase> phases = []; // Będzie ładowane z SharedPreferences lub domyślne

  // Kolory dla różnych celów
  final Map<String, Color> goalColors = {
    'pracady': const Color(0xFF4CAF50), // Zielony
    'silownia': const Color(0xFFFF9800), // Pomarańczowy
    'boks': const Color(0xFFF44336), // Czerwony
    'zarobek': const Color(0xFF2196F3), // Niebieski
    'inf04': const Color(0xFF9C27B0), // Fioletowy
    'matematyka': const Color(0xFF00BCD4), // Cyjan
    'wyjazdy': const Color(0xFFFFEB3B), // Żółty
  };

  @override
  void initState() {
    super.initState();
    currentDate = DateTime.now(); // Ustawiamy bieżącą datę
    _updateProgressData();
    _loadPhases(); // Ładowanie danych przy starcie
    initializeDateFormatting('pl_PL', null);
  }

  Color _getGoalColor(String goalId) {
    return goalColors[goalId] ?? const Color(0xFFBB86FC); // Domyślny kolor jeśli nie znajdziemy
  }

  // Definicja domyślnych faz i celów
  List<Phase> _getDefaultPhases() {
    // Definicje unikalnych typów celów z domyślnymi wartościami początkowymi i ikonami
    // Ich progress i maxProgress będą zapisywane per faza
    // (tj. cel "Siłownia" w Faza 1 jest odrębnym obiektem od "Siłownia" w Faza 2)
    Goal createGoal(String id, String title, String description, double maxProgress, IconData icon) {
      return Goal(id: id, title: title, description: description, maxProgress: maxProgress, icon: icon);
    }

    final List<Goal> allPossibleGoals = [
      createGoal('pracady', 'Przepracowane dni', 'Ilość dni przepracowanych w te wakacje.', 60, Icons.work),
      createGoal('silownia', 'Treningi siłowe', 'Ilość wykonanych treningów na siłowni.', 30, Icons.fitness_center),
      createGoal('boks', 'Treningi boksu', 'Ilość sesji treningowych boksu.', 20, Icons.sports_mma),
      createGoal('zarobek', 'Zarobione pieniądze', 'Suma zarobionych pieniędzy (w tysiącach PLN).', 10, Icons.attach_money),
      createGoal('inf04', 'Nauka INF04', 'Ilość godzin poświęconych na naukę INF04.', 80, Icons.computer),
      createGoal('matematyka', 'Nauka matematyki', 'Ilość godzin poświęconych na naukę matematyki.', 60, Icons.calculate),
      createGoal('wyjazdy', 'Wyjazdy', 'Lista planowanych wyjazdów w wakacje. (1 - zrealizowany)', 1, Icons.card_travel), // Binary goal
    ];

    // Funkcja pomocnicza do klonowania celów dla konkretnej fazy
    List<Goal> _cloneGoals(List<String> goalIds) {
      return goalIds.map((id) {
        final goalDef = allPossibleGoals.firstWhere((g) => g.id == id);
        return Goal(
          id: goalDef.id,
          title: goalDef.title,
          description: goalDef.description,
          maxProgress: goalDef.maxProgress, // Domyślna wartość docelowa
          icon: goalDef.icon,
        );
      }).toList();
    }

    return [
      Phase(
        title: "FAZA 1: Wakacje 2025",
        startDate: DateTime(2025, 6, 23), // Typowe daty wakacji
        endDate: DateTime(2025, 8, 31),
        description: "Wszystkie wydarzenia",
        goals: _cloneGoals(['pracady', 'silownia', 'boks', 'zarobek', 'inf04', 'matematyka', 'wyjazdy']),
      ),
      Phase(
        title: "FAZA 2: Szkoła 2025/2026",
        startDate: DateTime(2025, 9, 1),
        endDate: DateTime(2026, 6, 20),
        description: "Wszystkie wydarzenia poza pracą",
        goals: _cloneGoals(['silownia', 'boks', 'zarobek', 'inf04', 'matematyka']), // Praca wykluczona
      ),
      Phase(
        title: "FAZA 3: Wakacje 2026",
        startDate: DateTime(2026, 6, 21),
        endDate: DateTime(2026, 8, 31),
        description: "Wszystkie wydarzenia poza pracą/INF04",
        goals: _cloneGoals(['silownia', 'boks', 'zarobek', 'matematyka', 'wyjazdy']), // Praca i INF04 wykluczone
      ),
      Phase(
        title: "FAZA 4: Szkoła 2026/2027",
        startDate: DateTime(2026, 9, 1),
        endDate: DateTime(2027, 6, 20),
        description: "Wszystkie wydarzenia poza INF04",
        goals: _cloneGoals(['pracady', 'silownia', 'boks', 'zarobek', 'matematyka']), // INF04 wykluczone
      ),
    ];
  }


  void _updateProgressData() {
    setState(() {
      daysPassed = currentDate.difference(projectStartDate);
      daysToGo = projectEndDate.difference(currentDate);
      totalProjectProgress = daysPassed.inDays / projectEndDate.difference(projectStartDate).inDays;
      currentPhaseIndex = _getCurrentPhaseIndex();
    });
  }

  int _getCurrentPhaseIndex() {
    for (int i = 0; i < phases.length; i++) {
      if (currentDate.isAfter(phases[i].startDate.subtract(const Duration(days: 1))) &&
          currentDate.isBefore(phases[i].endDate.add(const Duration(days: 1)))) {
        return i;
      }
    }
    // Jeśli poza zakresem faz, ustaw na ostatnią, lub 0 jeśli jeszcze nie było faz
    if (phases.isEmpty) return 0;
    if (currentDate.isBefore(phases.first.startDate)) return 0;
    return phases.length - 1;
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  // =========================================================================
  // ZARZĄDZANIE DANYMI (ŁADOWANIE/ZAPIS)
  // =========================================================================

  Future<void> _loadPhases() async {
    final prefs = await SharedPreferences.getInstance();
    final String? phasesJson = prefs.getString('saved_phases');

    if (phasesJson != null && phasesJson.isNotEmpty) {
      try {
        final List<dynamic> jsonList = jsonDecode(phasesJson);
        setState(() {
          phases = jsonList.map((item) => Phase.fromJson(item as Map<String, dynamic>)).toList();
        });
      } catch (e) {
        print('Error loading phases from SharedPreferences: $e');
        // W razie błędu parsowania, załaduj domyślne
        setState(() {
          phases = _getDefaultPhases();
        });
      }
    } else {
      // Jeśli brak zapisanych danych, załaduj domyślne fazy
      setState(() {
        phases = _getDefaultPhases();
      });
    }

    _tabController = TabController(length: phases.length + 1, vsync: this);
    _tabController.addListener(() {
      setState(() {}); // Odśwież UI po zmianie tabu
    });

    _updateProgressData(); // Po załadowaniu danych zaktualizuj ogólny progress
  }

  Future<void> _savePhases() async {
    final prefs = await SharedPreferences.getInstance();
    final String phasesJson = jsonEncode(phases.map((p) => p.toJson()).toList());
    await prefs.setString('saved_phases', phasesJson);
  }

  void _updateGoalProgress(int phaseIndex, int goalIndex, double newProgress) {
    if (phaseIndex >= phases.length || goalIndex >= phases[phaseIndex].goals.length) return;
    setState(() {
      phases[phaseIndex].goals[goalIndex].progress = newProgress;
      _savePhases();
    });
  }

  void _updateGoalMaxProgress(int phaseIndex, int goalIndex, double newMaxProgress) {
    if (phaseIndex >= phases.length || goalIndex >= phases[phaseIndex].goals.length) return;
    setState(() {
      final goal = phases[phaseIndex].goals[goalIndex];
      goal.maxProgress = newMaxProgress;
      // Ensure current progress doesn't exceed new maxProgress
      if (goal.progress > newMaxProgress) {
        goal.progress = newMaxProgress;
      }
      _savePhases();
    });
  }

  // =========================================================================
  // BUDOWANIE INTERFEJSU UŻYTKOWNIKA
  // =========================================================================

  @override
  Widget build(BuildContext context) {
    if (phases.isEmpty) {
      return const Scaffold(
        backgroundColor: Color(0xFF121212),
        body: Center(child: CircularProgressIndicator()), // Pokaż ładowanie
      );
    }

    return Scaffold(
      backgroundColor: const Color(0xFF121212),
      appBar: AppBar(
        backgroundColor: const Color(0xFF1E1E1E),
        title: const Text(
          'TIMELAPSE',
          style: TextStyle(
            fontWeight: FontWeight.bold,
            letterSpacing: 2,
            color: Colors.white,
          ),
        ),
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(60),
          child: Container(
            height: 60,
            padding: const EdgeInsets.symmetric(horizontal: 16),
            color: const Color(0xFF1E1E1E),
            child: TabBar(
              controller: _tabController,
              isScrollable: true,
              indicator: BoxDecoration(
                borderRadius: BorderRadius.circular(10),
                color: const Color(0xFFBB86FC).withOpacity(0.2),
              ),
              indicatorSize: TabBarIndicatorSize.tab,
              labelColor: Colors.white,
              unselectedLabelColor: Colors.grey,
              tabs: [
                const Tab(text: 'PODSUMOWANIE'),
                ...phases.map((phase) => Tab(text: phase.title)).toList(),
              ],
            ),
          ),
        ),
      ),
      body: Container(
        color: const Color(0xFF121212),
        child: TabBarView(
          controller: _tabController,
          children: [
            _buildMainTab(),
            ...phases.asMap().entries.map((entry) => _buildPhaseTab(entry.key)).toList(),
          ],
        ),
      ),
    );
  }

  Widget _buildMainTab() {
    return Container(
      color: const Color(0xFF121212),
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _buildProgressCard(),
            const SizedBox(height: 20),
            _buildCurrentPhaseCard(),
            const SizedBox(height: 20),
            _buildUpcomingGoals(),
          ],
        ),
      ),
    );
  }

