              barRadius: const Radius.circular(10),
              progressColor: isBeforeStart ? Colors.grey : _getProgressColor(totalProjectProgress),
              backgroundColor: Colors.grey.shade800,
              padding: EdgeInsets.zero,
            ),
            const SizedBox(height: 16),
            if (!isBeforeStart) // Only show days remaining if we've started
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  'Pozostało: ${daysToGo.inDays} dni',
                  style: TextStyle(
                    fontSize: 14,
                    color: Colors.white.withOpacity(0.7),
