  Color _getProgressColor(double progress) {
    if (progress < 0.3) return const Color(0xFFCF6679); // Czerwony/różowy
    if (progress < 0.7) return const Color(0xFFFFD166); // Żółty/pomarańczowy
    return const Color(0xFF05D577); // Zielony
  }

