              ],
            ),
          ],
        ),
      ),
    );
  }

  double _calculatePhaseProgress(int phaseIndex) {
    if (phaseIndex >= phases.length) return 0.0;
    Phase phase = phases[phaseIndex];
    if (currentDate.isBefore(phase.startDate)) return 0.0;
    if (currentDate.isAfter(phase.endDate)) return 1.0;

    // Upewnij się, że nie dzielimy przez zero
    final totalPhaseDuration = phase.endDate.difference(phase.startDate).inDays;
    if (totalPhaseDuration == 0) return 0.0;

    return currentDate.difference(phase.startDate).inDays / totalPhaseDuration;
  }

