  // =========================================================================
  // MODALE DLA ZARZĄDZANIA CELEM
  // =========================================================================

  // Modal do aktualizacji BIEŻĄCEGO progressu
  void _showGoalProgressDialog(int phaseIndex, int goalIndex, Goal goal) {
    double newProgress = goal.progress;
    bool isBinaryGoal = goal.maxProgress == 1;
    final Color goalColor = _getGoalColor(goal.id);

    showDialog(
      context: context,
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setState) {
            return AlertDialog(
              backgroundColor: const Color(0xFF1E1E1E),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(20),
              ),
              title: Text(
                'Aktualizuj postęp - ${goal.title}',
                style: const TextStyle(
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
              ),
              content: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      goal.description,
                      style: TextStyle(
                        fontSize: 14,
                        color: Colors.white.withOpacity(0.7),
                      ),
                    ),
                    const SizedBox(height: 20),
                    if (isBinaryGoal)
                      SwitchListTile(
                        title: const Text(
                          'Cel osiągnięty',
                          style: TextStyle(color: Colors.white),
                        ),
                        value: newProgress >= 1,
                        activeColor: goalColor,
                        onChanged: (value) {
                          setState(() {
                            newProgress = value ? 1 : 0;
                          });
                        },
                      )
                    else
                      Column(
                        children: [
                          Row(
                            children: [
                              const Text(
                                'Postęp: ',
                                style: TextStyle(color: Colors.white),
                              ),
                              Expanded(
                                child: Slider(
                                  value: newProgress,
                                  min: 0,
                                  max: goal.maxProgress,
                                  divisions: goal.maxProgress.toInt() > 0 ? goal.maxProgress.toInt() : 1, // Zapewnij min 1 podział
                                  activeColor: goalColor,
                                  inactiveColor: Colors.grey.shade700,
                                  label: newProgress.toStringAsFixed(0),
                                  onChanged: (value) {
                                    setState(() {
                                      newProgress = value;
                                    });
                                  },
                                ),
                              ),
                              Text(
                                newProgress.toStringAsFixed(0),
                                style: const TextStyle(color: Colors.white),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              IconButton(
                                icon: const Icon(Icons.remove, color: Colors.white),
                                onPressed: () {
                                  setState(() {
                                    newProgress = (newProgress - 1).clamp(0, goal.maxProgress);
                                  });
                                },
                              ),
                              IconButton(
                                icon: const Icon(Icons.add, color: Colors.white),
                                onPressed: () {
                                  setState(() {
                                    newProgress = (newProgress + 1).clamp(0, goal.maxProgress);
                                  });
                                },
                              ),
                            ],
                          ),
                        ],
                      ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(context),
                  child: Text(
                    'Anuluj',
                    style: TextStyle(
                      color: Colors.white.withOpacity(0.7),
                    ),
                  ),
                ),
                ElevatedButton(
                  onPressed: () {
                    _updateGoalProgress(phaseIndex, goalIndex, newProgress);
                    Navigator.pop(context);
                  },
                  style: ElevatedButton.styleFrom(
                    backgroundColor: goalColor,
                    foregroundColor: Colors.white,
                  ),
                  child: const Text('Zapisz', style: TextStyle(color: Colors.white)),
                ),
              ],
            );
          },
        );
      },
    );
  }

  // Nowy modal do aktualizacji CAŁKOWITEJ wartości docelowej
  void _showGoalMaxProgressDialog(int phaseIndex, int goalIndex, Goal goal) {
    TextEditingController controller = TextEditingController(text: goal.maxProgress.toStringAsFixed(0));
    final Color goalColor = _getGoalColor(goal.id);

    showDialog(
      context: context,
      builder: (context) {
        return AlertDialog(
          backgroundColor: const Color(0xFF1E1E1E),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          title: Text(
            'Ustaw wartość docelową - ${goal.title}',
            style: const TextStyle(
              fontWeight: FontWeight.bold,
              color: Colors.white,
            ),
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'Wpisz nową wartość docelową dla celu "${goal.title}":',
                style: TextStyle(
                  fontSize: 14,
                  color: Colors.white.withOpacity(0.7),
                ),
              ),
              const SizedBox(height: 20),
              TextField(
                controller: controller,
                keyboardType: TextInputType.number,
                textAlign: TextAlign.center,
                style: const TextStyle(color: Colors.white, fontSize: 24),
                decoration: InputDecoration(
                  filled: true,
                  fillColor: Colors.grey.shade800,
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                    borderSide: BorderSide.none,
                  ),
                  contentPadding: const EdgeInsets.symmetric(vertical: 15),
                ),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: Text(
                'Anuluj',
                style: TextStyle(
                  color: Colors.white.withOpacity(0.7),
                ),
              ),
            ),
            ElevatedButton(
              onPressed: () {
                double? newValue = double.tryParse(controller.text);
                if (newValue != null && newValue >= 0) {
                  _updateGoalMaxProgress(phaseIndex, goalIndex, newValue);
                  Navigator.pop(context);
                } else {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(content: Text('Wprowadź poprawną liczbę dodatnią.')),
                  );
                }
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: goalColor,
                foregroundColor: Colors.white,
              ),
              child: const Text('Zapisz', style: TextStyle(color: Colors.white)),
            ),
          ],
        );
      },
    );
  }
}

