  final inf04 = createGoal('inf04', 'Nauka INF04', 'Ilość godzin poświęconych na naukę INF04.', 80, Icons.computer);
  final matematyka = createGoal('matematyka', 'Nauka matematyki', 'Ilość godzin poświęconych na naukę matematyki.', 60, Icons.calculate);
  final fizyka = createGoal('fizyka', 'Nauka fizyki', 'Ilość godzin poświęconych na naukę fizyki.', 60, Icons.science);

  // Grupy
  final silaGroup = GoalGroup(
    groupName: "Siła",
