      endDate: DateTime(2025, 8, 31),
      description: "Wszystkie wydarzenia",
      goalGroups: [finanseGroup, silaGroup, edukacjaGroup],
    ),
    // Dodaj inne fazy analogicznie, jeśli chcesz
  ];
}
