### 4. Modyfikacja UI do wyświetlania grup i celów

W miejscach, gdzie wyświetlasz cele, musisz teraz iterować po grupach i po celach w grupach.

Przykład dla `_buildUpcomingGoals()`:

```dart
Widget _buildUpcomingGoals() {
  if (phases.isEmpty || phases[currentPhaseIndex].goalGroups.isEmpty) {
    return Card(
      color: const Color(0xFF1E1E1E),
      child: Padding(
        padding: const EdgeInsets.all(20),
        child: Center(
          child: Column(
            children: [
              Icon(
                Icons.check_circle_outline,
                size: 40,
                color: Colors.grey.shade500,
              ),
              const SizedBox(height: 12),
              Text(
                'Brak celów w tej fazie lub wszystkie cele zostały osiągnięte',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 16,
                  color: Colors.grey.shade500,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  return Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      for (var group in phases[currentPhaseIndex].goalGroups) ...[
        Text(
          group.groupName,
          style: const TextStyle(
            fontSize: 22,
            fontWeight: FontWeight.bold,
            color: Colors.white,
          ),
        ),
        Text(
          group.groupDescription,
          style: TextStyle(
            fontSize: 14,
            color: Colors.white.withOpacity(0.7),
          ),
        ),
        const SizedBox(height: 10),
        ...group.goals.asMap().entries.map((entry) {
          int goalIndex = entry.key;
          Goal goal = entry.value;
          double progressPercentage = (goal.maxProgress > 0) ? goal.progress / goal.maxProgress : 0.0;
          return _buildGoalProgressTile(currentPhaseIndex, goalIndex, goal, progressPercentage);
        }).toList(),
        const SizedBox(height: 20),
      ],
    ],
  );
}
```

---

### 5. Aktualizacja metod aktualizacji postępu

Musisz zmodyfikować metody `_updateGoalProgress` i `_updateGoalMaxProgress`, aby uwzględniały indeks grupy i indeks celu w grupie, np.:

```dart
void _updateGoalProgress(int phaseIndex, int groupIndex, int goalIndex, double newProgress) {
  if (phaseIndex >= phases.length) return;
  if (groupIndex >= phases[phaseIndex].goalGroups.length) return;
  if (goalIndex >= phases[phaseIndex].goalGroups[groupIndex].goals.length) return;

  setState(() {
    phases[phaseIndex].goalGroups[groupIndex].goals[goalIndex].progress = newProgress;
    _savePhases();
  });
}

void _updateGoalMaxProgress(int phaseIndex, int groupIndex, int goalIndex, double newMaxProgress) {
  if (phaseIndex >= phases.length) return;
  if (groupIndex >= phases[phaseIndex].goalGroups.length) return;
  if (goalIndex >= phases[phaseIndex].goalGroups[groupIndex].goals.length) return;

  setState(() {
    final goal = phases[phaseIndex].goalGroups[groupIndex].goals[goalIndex];
    goal.maxProgress = newMaxProgress;
    if (goal.progress > newMaxProgress) {
      goal.progress = newMaxProgress;
    }
    _savePhases();
  });
}
```

