```gdscript
class_name LuckEffect
extends Resource

var effect_function: Callable
var description: String

func _init(p_effect_function: Callable, p_description: String):
    effect_function = p_effect_function
    description = p_description

func apply(player: MainPlayer) -> void:
    effect_function.call(player)

class_name LuckTable
extends Resource

var outcomes = {}

func _init():
    # Bad outcomes (1-2)
    outcomes[1] = [
        LuckEffect.new(
            func(player: MainPlayer): player.change_max_health_by(-player.max_health / 3),
            "Decreased max health by 33%"
        ),
        LuckEffect.new(
            func(player: MainPlayer): player.fire_time_reduction_percentage -= 10,
            "Decreased firing speed by 10%"
        )
    ]

    outcomes[2] = [
        LuckEffect.new(
            func(player: MainPlayer): player.currency -= 500, # Fixed to match description
            "Lost 500 ink"
        ),
        LuckEffect.new(
            func(player: MainPlayer): player.speed_boosts.append(-10),
            "Movement speed decreased by 10"
        )
    ]

    # Neutral outcomes (3-4)
    outcomes[3] = [
        LuckEffect.new(
            func(player: MainPlayer): player.stamina_regen_time_multiplier += 0.1,
            "Stamina regeneration slowed by 10%"
        )
    ]

    outcomes[4] = [
        LuckEffect.new(
            func(player: MainPlayer): player.stamina_regen_time_multiplier += 0.1,
            "Stamina regeneration slowed by 10%"
        )
    ]

    # Good outcomes (5-6)
    outcomes[5] = [
        LuckEffect.new(
            func(player: MainPlayer): player.currency += 500, # Fixed to match description
            "Gained 500 Ink"
        ),
        LuckEffect.new(
            func(player: MainPlayer): player.speed_boosts.append(15),
            "Movement speed increased by 15"
        )
    ]

    outcomes[6] = [
        LuckEffect.new(
            func(player: MainPlayer): player.change_max_health_by(player.max_health / 2),
            "Increased max health by 50%"
        ),
        LuckEffect.new(
            func(player: MainPlayer): player.fire_time_reduction_percentage += 7,
            "Increased firing speed by 7%"
        )
    ]

func apply_outcome(roll: int, player: MainPlayer) -> Array[String]:
    var messages = []
    if outcomes.has(roll):
        for effect in outcomes[roll]:
            effect.apply(player)
            messages.append(effect.description)
    return messages

# Example usage:
